/**
 * Bundled model catalog (generated by `scripts/build-catalog.mjs`) plus helpers
 * used by the model picker and the reasoning selector.
 */
import catalogJson from '@data/catalog.json';
import type {
  CatalogFile,
  ModelInfo,
  ModelSelection,
  ProviderInfo,
  ReasoningOption,
  ReasoningSelection,
  Settings,
} from './types';

export const catalog = catalogJson as unknown as CatalogFile;

export function providers(): ProviderInfo[] {
  return catalog.providers;
}

export function getProvider(providerId: string): ProviderInfo | undefined {
  return catalog.providers.find((p) => p.id === providerId);
}

export function getModel(providerId: string, modelId: string): ModelInfo | undefined {
  return getProvider(providerId)?.models.find((m) => m.id === modelId);
}

export function findModel(modelId: string): { provider: ProviderInfo; model: ModelInfo } | null {
  for (const provider of catalog.providers) {
    const model = provider.models.find((m) => m.id === modelId);
    if (model) return { provider, model };
  }
  return null;
}

export function providerLabel(providerId: string): string {
  return getProvider(providerId)?.shortName ?? providerId;
}

export function defaultSelection(settings?: Settings | null): ModelSelection {
  const providerId = settings?.defaultProvider ?? 'opencode-go';
  const provider = getProvider(providerId) ?? providers()[0];
  const configured = settings?.defaultModel;
  const modelId =
    configured && provider?.models.some((m) => m.id === configured)
      ? configured
      : (provider?.defaultModelId ?? provider?.models[0]?.id ?? '');
  const model = provider?.models.find((m) => m.id === modelId);
  const preferred = settings?.reasoningDefault;
  const ui = reasoningUi(model);
  let reasoning = defaultReasoningFor(model);
  if (preferred === 'off' && ui.canDisable) {
    reasoning = { mode: 'off' };
  } else if (preferred && ui.efforts.includes(preferred)) {
    reasoning = { mode: 'effort', effort: preferred };
  }
  return {
    providerId: provider?.id ?? providerId,
    modelId,
    reasoning,
  };
}

/** Picks the first available reasoning option as the default. */
export function defaultReasoningFor(model?: ModelInfo | null): ReasoningSelection | null {
  if (!model) return null;
  const hasToggle = model.reasoningOptions.some((o) => o.type === 'toggle');
  const effort = model.reasoningOptions.find((o) => o.type === 'effort') as
    | { type: 'effort'; values: string[] }
    | undefined;
  if (effort) {
    // Default to a balanced effort when the model exposes one.
    const preferred = ['medium', 'high', 'low', 'max', 'xhigh', 'minimal'].find((v) =>
      effort.values.includes(v),
    );
    return { mode: 'effort', effort: preferred ?? effort.values[0] ?? null };
  }
  if (hasToggle) return { mode: 'off' };
  const budget = model.reasoningOptions.find((o) => o.type === 'budget_tokens') as
    | { type: 'budget_tokens'; min?: number; max?: number }
    | undefined;
  if (budget) {
    // Budget-only models have no on/off switch: always send a concrete budget so
    // the slider value shown in the UI matches what is committed.
    const min = budget.min ?? 1_024;
    const max = budget.max ?? 65_536;
    return { mode: 'budget', budget: Math.min(max, Math.max(min, 8_192)) };
  }
  return null;
}

export interface ReasoningUi {
  /** false when the model has no reasoning control at all */
  supported: boolean;
  canDisable: boolean;
  efforts: string[];
  budget: { min: number | null; max: number | null } | null;
  /** the reasoning options that are meaningful for this model */
  options: ReasoningOption[];
}

export function reasoningUi(model?: ModelInfo | null): ReasoningUi {
  if (!model) {
    return { supported: false, canDisable: false, efforts: [], budget: null, options: [] };
  }
  const options = model.reasoningOptions ?? [];
  const toggle = options.find((o) => o.type === 'toggle');
  const effort = options.find((o) => o.type === 'effort') as
    | { type: 'effort'; values: string[] }
    | undefined;
  const budget = options.find((o) => o.type === 'budget_tokens') as
    | { type: 'budget_tokens'; min?: number; max?: number }
    | undefined;
  return {
    supported: Boolean(toggle || effort || budget),
    canDisable: Boolean(toggle) || Boolean(effort?.values.includes('none')),
    efforts: effort?.values ?? [],
    budget: budget ? { min: budget.min ?? 1024, max: budget.max ?? 65536 } : null,
    options,
  };
}

/** Human label for an effort value. */
export function effortLabel(effort: string): string {
  const map: Record<string, string> = {
    none: 'Desligado',
    minimal: 'Mínimo',
    low: 'Baixo',
    medium: 'Médio',
    high: 'Alto',
    xhigh: 'Muito alto',
    max: 'Máximo',
  };
  return map[effort] ?? effort;
}

/** Compact reasoning label used inside pills (e.g. "Máx."). */
export function reasoningShortLabel(
  model: ModelInfo | undefined,
  selection: ReasoningSelection | null | undefined,
): string {
  if (!model || !reasoningUi(model).supported) return '';
  if (!selection || selection.mode === 'off') {
    return reasoningUi(model).canDisable ? 'off' : '';
  }
  if (selection.mode === 'effort') {
    return selection.effort ? effortLabel(selection.effort) : 'on';
  }
  if (selection.mode === 'budget') return String(selection.budget ?? 0);
  return '';
}

export function reasoningLabel(
  model: ModelInfo | undefined,
  selection: ReasoningSelection | null | undefined,
): string {
  if (!model || !reasoningUi(model).supported) return 'Sem controle';
  if (!selection || selection.mode === 'off') {
    return reasoningUi(model).canDisable ? 'Pensamento off' : 'Padrão';
  }
  if (selection.mode === 'effort') {
    if (!selection.effort) return 'Pensamento ligado';
    return `Pensamento ${effortLabel(selection.effort)}`;
  }
  if (selection.mode === 'budget') return `Orçamento ${selection.budget ?? 0}`;
  return 'Padrão';
}

export function formatContextWindow(tokens: number): string {
  if (!tokens) return '—';
  if (tokens >= 1_000_000) {
    // 1_048_576 is "1M", not "1.0M": round to one decimal and drop the ".0".
    const rounded = Math.round((tokens / 1_000_000) * 10) / 10;
    return Number.isInteger(rounded) ? `${rounded.toFixed(0)}M` : `${rounded.toFixed(1)}M`;
  }
  if (tokens >= 1000) return `${Math.round(tokens / 1000)}K`;
  return String(tokens);
}

export function formatPrice(cost?: ModelInfo['cost']): string {
  if (!cost || cost.input == null || cost.output == null) return '—';
  if (cost.input === 0 && cost.output === 0) return 'Grátis';
  const fmt = (v: number) => (v === 0 ? 'grátis' : `$${v.toFixed(2)}`);
  return `${fmt(cost.input)} / ${fmt(cost.output)}`;
}

export function modelBadges(model: ModelInfo): string[] {
  const badges: string[] = [];
  if (model.status === 'free') badges.push('Grátis');
  if (model.tags.includes('vision') || model.attachment) badges.push('Visão');
  if (model.reasoningOptions.length) badges.push('Raciocínio');
  if (model.openWeights) badges.push('Open');
  if (model.status === 'beta') badges.push('Preview');
  if (model.status === 'unavailable') badges.push('Indisponível');
  return badges;
}

export function supportsAttachments(model?: ModelInfo | null): boolean {
  if (!model) return false;
  return model.attachment || model.modalities.input.includes('image');
}

/** Group models by family for the picker list. */
export function groupByFamily(models: ModelInfo[]): { family: string; models: ModelInfo[] }[] {
  const map = new Map<string, ModelInfo[]>();
  for (const model of models) {
    const family = model.family || 'outros';
    const list = map.get(family) ?? [];
    list.push(model);
    map.set(family, list);
  }
  return [...map.entries()]
    .map(([family, list]) => ({
      family,
      models: list.sort((a, b) => a.name.localeCompare(b.name)),
    }))
    .sort((a, b) => a.family.localeCompare(b.family));
}

export const CATALOG_GENERATED_AT = catalog.generatedAt;
